-- Independent Dadyoom formative comprehension / speaking questions.
-- These are NOT the official Ministry book questions; scoped to verified plan
-- titles and existing ORIGINAL Dadyoom texts of Bahrain grade 3 term 1.
-- Add only when no question already occupies the lesson/question_order.
WITH proposed(lesson_id,question_order,question,options,correct_answer,explanation) AS (
VALUES
('652648df-d730-448d-89e2-240980456c4d'::uuid,1,'كيف طلب سامر المشاركة في اللعب؟','[{"id":"a","text":"قاطع الأطفال وهم يلعبون"},{"id":"b","text":"انتظر نهاية الجولة وطلب بأدب"},{"id":"c","text":"أخذ الكرة دون استئذان"},{"id":"d","text":"غادر الساحة غاضبًا"}]'::jsonb,'b','انتظر سامر انتهاء الجولة ثم سأل الأطفال بأدب إن كانوا يسمحون له بالمشاركة.'),
('652648df-d730-448d-89e2-240980456c4d'::uuid,2,'كيف ساعد الأطفال الجميع على المشاركة؟','[{"id":"a","text":"ألغوا اللعبة"},{"id":"b","text":"لعب كل طفل وحده"},{"id":"c","text":"تقاسموا الوقت وتبادلوا الأدوار"},{"id":"d","text":"منعوا سامر من اللعب"}]'::jsonb,'c','اقترحت مريم تقسيم الوقت، ثم تبادل الأطفال الأدوار ليشارك الجميع.'),
('652648df-d730-448d-89e2-240980456c4d'::uuid,3,'ماذا فعل الأطفال عندما أخطأ زميلهم في تمرير الكرة؟','[{"id":"a","text":"شجعوه بدل السخرية"},{"id":"b","text":"سخروا منه"},{"id":"c","text":"أخرجوه من الملعب"},{"id":"d","text":"أنهوا اللعب فورًا"}]'::jsonb,'a','شجع الأطفال زميلهم بدلاً من السخرية منه، وهذا سلوك احترام وتعاون.'),
('ce650924-9d00-4ad6-b5ab-c1302ae33a90'::uuid,1,'لماذا طلبت لجين الإذن قبل تصوير زميلاتها؟','[{"id":"a","text":"لأنها نسيت الهاتف"},{"id":"b","text":"لتؤخر التصوير"},{"id":"c","text":"حتى تختار لعبة جديدة"},{"id":"d","text":"احترامًا لخصوصيتهن"}]'::jsonb,'d','طلب الإذن قبل تصوير الآخرين يحترم خصوصيتهم.'),
('ce650924-9d00-4ad6-b5ab-c1302ae33a90'::uuid,2,'ماذا يساعد على جعل الصورة أوضح في نص ضاديوم؟','[{"id":"a","text":"تحريك الهاتف بسرعة"},{"id":"b","text":"تثبيت اليدين والانتباه للخلفية"},{"id":"c","text":"التقاطها في الظلام دائمًا"},{"id":"d","text":"تغطية عدسة الهاتف"}]'::jsonb,'b','لاحظت لجين أن تثبيت اليدين والانتباه إلى الخلفية يجعل الصورة أوضح.'),
('ce650924-9d00-4ad6-b5ab-c1302ae33a90'::uuid,3,'كيف صورت لجين الزهرة؟','[{"id":"a","text":"قطفتها قبل التصوير"},{"id":"b","text":"أزالت أوراقها"},{"id":"c","text":"التقطت صورة دون أن تلمسها"},{"id":"d","text":"كسرت غصنها"}]'::jsonb,'c','التقطت لجين صورة للزهرة دون لمسها، فاحترمت النبات.'),
('34cb7a04-47d8-4b59-ba62-a0af0b1bf0cf'::uuid,1,'ماذا وجدت هدى داخل الصندوق القديم؟','[{"id":"a","text":"رسائل وصورًا وقصصًا عائلية"},{"id":"b","text":"قطعًا ذهبية فقط"},{"id":"c","text":"ألعابًا جديدة"},{"id":"d","text":"أجهزة تصوير"}]'::jsonb,'a','عثرَت هدى على رسائل وصور وقصص كتبها أفراد الأسرة.'),
('34cb7a04-47d8-4b59-ba62-a0af0b1bf0cf'::uuid,2,'لماذا رأت هدى أن الصندوق كنز رغم عدم وجود ذهب؟','[{"id":"a","text":"لأنه كان ثقيلًا"},{"id":"b","text":"لأنه كبير الحجم"},{"id":"c","text":"لأنه مليء بالأوراق الفارغة"},{"id":"d","text":"لأنه يحفظ الذكريات والمعرفة"}]'::jsonb,'d','فهمت هدى أن الذكريات والمعرفة قد تكون أثمن من الذهب.'),
('34cb7a04-47d8-4b59-ba62-a0af0b1bf0cf'::uuid,3,'ماذا فعلت الأسرة للحفاظ على الرسائل؟','[{"id":"a","text":"ألقتها خارج المنزل"},{"id":"b","text":"حفظتها في مكان آمن"},{"id":"c","text":"أعطتها لشخص غريب"},{"id":"d","text":"مزقتها"}]'::jsonb,'b','حفظت الأسرة الرسائل في مكان آمن لتبقى للأجيال.'),
('3eeb992f-6111-4a41-aac2-b61b7a4c3b8a'::uuid,1,'ماذا يفعل خالد بما يستعيره من الآخرين؟','[{"id":"a","text":"يخفيه"},{"id":"b","text":"يحتفظ به لنفسه"},{"id":"c","text":"يعيده إلى صاحبه"},{"id":"d","text":"يتركه في الساحة"}]'::jsonb,'c','قال خالد إنه يحافظ على أشيائه ويعيد ما استعاره، وهذا من الأمانة.'),
('3eeb992f-6111-4a41-aac2-b61b7a4c3b8a'::uuid,2,'كيف تُظهر هند احترامها لمن يتحدث؟','[{"id":"a","text":"تستمع حتى ينتهي من الكلام"},{"id":"b","text":"تقاطعه باستمرار"},{"id":"c","text":"تنظر بعيدًا وتضحك"},{"id":"d","text":"تتحدث بصوت أعلى"}]'::jsonb,'a','قالت هند إنها تستمع إلى زميلتها حتى تنتهي من الكلام.'),
('3eeb992f-6111-4a41-aac2-b61b7a4c3b8a'::uuid,3,'ما الخطوة التي يتخذها أحمد قبل مساعدة زميله؟','[{"id":"a","text":"يفرض عليه طريقة واحدة"},{"id":"b","text":"يتركه دون سؤال"},{"id":"c","text":"يأخذ أدواته"},{"id":"d","text":"يسأله عن الطريقة التي تناسبه"}]'::jsonb,'d','يسأل أحمد الطالب عن الطريقة التي تناسبه قبل أن يقدم المساعدة.'),
('6f697bfc-8542-4455-b197-244bd8d21fd9'::uuid,1,'ماذا فعل يوسف عندما وجد قلمًا في الممر؟','[{"id":"a","text":"احتفظ به"},{"id":"b","text":"سلّمه للمعلم ليعود لصاحبه"},{"id":"c","text":"أخفاه في حقيبته"},{"id":"d","text":"ألقاه بعيدًا"}]'::jsonb,'b','أخبر يوسف المعلم وسلمه القلم ليُعاد إلى صاحبه.'),
('6f697bfc-8542-4455-b197-244bd8d21fd9'::uuid,2,'لماذا لم يحتفظ يوسف بالقلم؟','[{"id":"a","text":"لأن القلم كان مكسورًا"},{"id":"b","text":"لأنه لا يحب الأقلام"},{"id":"c","text":"لأنه ليس ملكًا له"},{"id":"d","text":"لأنه نسي حقيبته"}]'::jsonb,'c','رفض يوسف الاحتفاظ بشيء لا يملكه، التزامًا بالأمانة.'),
('6f697bfc-8542-4455-b197-244bd8d21fd9'::uuid,3,'ماذا تحقق الأمانة بين الناس وفق حديث يوسف؟','[{"id":"a","text":"الثقة"},{"id":"b","text":"الخصام"},{"id":"c","text":"الخوف"},{"id":"d","text":"الفوضى"}]'::jsonb,'a','قال يوسف إن الأمانة تجعل الناس يثق بعضهم ببعض.'),
('24344b9b-0a49-466b-ab1b-ed381fda4089'::uuid,1,'لماذا تحب سلمى هواية الرسم؟','[{"id":"a","text":"لأنها لا تحب الألوان"},{"id":"b","text":"كي تتجنب واجباتها"},{"id":"c","text":"لأنها لا تملك هواية أخرى"},{"id":"d","text":"لتعبر بالألوان عن أفكارها"}]'::jsonb,'d','ذكرت سلمى أن الرسم يساعدها على التعبير عن أفكارها بالألوان.'),
('24344b9b-0a49-466b-ab1b-ed381fda4089'::uuid,2,'أين يحب حمد ركوب الدراجة؟','[{"id":"a","text":"في طريق مزدحم وحده"},{"id":"b","text":"في مكان آمن مع عائلته"},{"id":"c","text":"داخل الفصل"},{"id":"d","text":"في مكان ممنوع"}]'::jsonb,'b','قال حمد إنه يحب ركوب الدراجة في مكان آمن مع عائلته.'),
('24344b9b-0a49-466b-ab1b-ed381fda4089'::uuid,3,'كيف نتعامل مع اختلاف هوايات الأصدقاء؟','[{"id":"a","text":"نسخر من هواياتهم"},{"id":"b","text":"نطلب منهم تركها"},{"id":"c","text":"نحترم اهتماماتهم"},{"id":"d","text":"نمنعهم من التحدث عنها"}]'::jsonb,'c','اتفق الطالبان على أن احترام اهتمامات الآخرين يجعل الحوار أجمل.')
), eligible AS (
 SELECT p.* FROM proposed p
 JOIN public.lessons l ON l.id=p.lesson_id
 JOIN public.units u ON u.id=l.unit_id
 JOIN public.grades g ON g.id=u.grade_id
 JOIN public.curricula c ON c.id=g.curriculum_id
 JOIN public.countries co ON co.id=c.country_id
 WHERE co.code='BH' AND g.grade_number=3 AND l.semester=1
 AND l.status='published'
 AND l.source_pdf_url='https://edunet.bh/manual/plans1-2026-2027/Arabic/Plan1.pdf'
)
INSERT INTO public.questions(lesson_id,question_order,question,question_type,options,correct_answer,explanation,points)
SELECT lesson_id,question_order,question,'multiple_choice',options,correct_answer,explanation,1
FROM eligible
ON CONFLICT (lesson_id,question_order) DO NOTHING
RETURNING lesson_id,question_order;